1	import Stripe from "stripe";
2	import { db } from "./db";
3	import type { OrderIntent } from "./order";
4	import { invoiceCreateData } from "./invoices";
5	
6	export function stripeConfigured(): boolean {
7	  return !!process.env.STRIPE_SECRET_KEY;
8	}
9	
10	let client: Stripe | null = null;
11	
12	export function stripe(): Stripe {
13	  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
14	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
15	  return client;
16	}
17	
18	/** Create a Checkout session that pays for a VPS order directly (no wallet pre-fund). */
19	export async function createOrderCheckout(
20	  user: { id: string; email: string },
21	  amountCents: number,
22	  intent: OrderIntent,
23	): Promise<string | null> {
24	  if (!stripeConfigured() || amountCents <= 0) return null;
25	  const base = process.env.APP_URL ?? "http://localhost:3000";
26	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
27	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
28	  const session = await stripe().checkout.sessions.create({
29	    mode: "payment",
30	    customer_email: user.email,
31	    line_items: [
32	      {
33	        price_data: {
34	          currency: "usd",
35	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
36	          unit_amount: amountCents,
37	        },
38	        quantity: 1,
39	      },
40	    ],
41	    metadata: { nxeonUserId: user.id, nxeonOrder: JSON.stringify(slim).slice(0, 490) },
42	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
43	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
44	  });
45	  return session.url;
46	}
47	
48	/**
49	 * Create a Checkout session that pays for a prorated server UPGRADE directly (no
50	 * wallet pre-fund), applying the customer's wallet balance to the split. The CARD
51	 * is charged only `cardCents` (the remainder after wallet credit); the FULL
52	 * proration is recorded in metadata as `chargeCents` so the confirm route debits
53	 * the whole proration back out of the wallet. Since creditCheckoutSession credited
54	 * only the card portion, the wallet naturally absorbs the difference — the wallet
55	 * is never touched before the card clears.
56	 */
57	export async function createResizeCheckout(
58	  user: { id: string; email: string },
59	  cardCents: number,
60	  resize: { serverId: string; planId: string; planName?: string; prorateCents: number },
61	): Promise<string | null> {
62	  if (!stripeConfigured() || cardCents <= 0) return null;
63	  const base = process.env.APP_URL ?? "http://localhost:3000";
64	  const session = await stripe().checkout.sessions.create({
65	    mode: "payment",
66	    customer_email: user.email,
67	    line_items: [
68	      {
69	        price_data: {
70	          currency: "usd",
71	          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
72	          unit_amount: cardCents,
73	        },
74	        quantity: 1,
75	      },
76	    ],
77	    metadata: {
78	      nxeonUserId: user.id,
79	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
80	      nxeonResize: JSON.stringify({ serverId: resize.serverId, planId: resize.planId, chargeCents: resize.prorateCents }).slice(0, 490),
81	    },
82	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
83	    cancel_url: `${base}/dashboard/servers/${resize.serverId}?canceled=1`,
84	  });
85	  return session.url;
86	}
87	
88	/**
89	 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
90	 * directly (no wallet pre-fund), applying the customer's wallet balance to the
91	 * split. Structurally identical to createResizeCheckout: the CARD is charged only
92	 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
93	 * in metadata as `chargeCents`, so the confirm route debits the whole proration
94	 * back out of the wallet against the just-credited card amount. The wallet is
95	 * never touched before the card clears.
96	 */
97	export async function createDiskExpandCheckout(
98	  user: { id: string; email: string },
99	  cardCents: number,
100	  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
101	): Promise<string | null> {
102	  if (!stripeConfigured() || cardCents <= 0) return null;
103	  const base = process.env.APP_URL ?? "http://localhost:3000";
104	  const session = await stripe().checkout.sessions.create({
105	    mode: "payment",
106	    customer_email: user.email,
107	    line_items: [
108	      {
109	        price_data: {
110	          currency: "usd",
111	          product_data: {
112	            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
113	            // The one-way nature is on the Stripe page itself, not just in our UI.
114	            description: "Permanent storage expansion — disk space can be added but never removed.",
115	          },
116	          unit_amount: cardCents,
117	        },
118	        quantity: 1,
119	      },
120	    ],
121	    metadata: {
122	      nxeonUserId: user.id,
123	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
124	      nxeonDiskExpand: JSON.stringify({
125	        serverId: expand.serverId,
126	        addGB: expand.addGB,
127	        chargeCents: expand.prorateCents,
128	      }).slice(0, 490),
129	    },
130	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
131	    cancel_url: `${base}/dashboard/servers/${expand.serverId}?canceled=1`,
132	  });
133	  return session.url;
134	}
135	
136	/** For the confirm route: the disk-expansion intent attached to a paid session, if any. */
137	export async function getCheckoutDiskExpandIntent(
138	  sessionId: string,
139	): Promise<{ userId: string; serverId: string; addGB: number; chargeCents: number } | null> {
140	  if (!stripeConfigured()) return null;
141	  try {
142	    const session = await stripe().checkout.sessions.retrieve(sessionId);
143	    const userId = session.metadata?.nxeonUserId;
144	    const raw = session.metadata?.nxeonDiskExpand;
145	    if (!userId || !raw || session.payment_status !== "paid") return null;
146	    const parsed = JSON.parse(raw) as { serverId: string; addGB: number; chargeCents: number };
147	    return { userId, serverId: parsed.serverId, addGB: parsed.addGB, chargeCents: parsed.chargeCents };
148	  } catch {
149	    return null;
150	  }
151	}
152	
153	/** For the confirm route: the resize intent attached to a paid session, if any. */
154	export async function getCheckoutResizeIntent(
155	  sessionId: string,
156	): Promise<{ userId: string; serverId: string; planId: string; chargeCents: number } | null> {
157	  if (!stripeConfigured()) return null;
158	  try {
159	    const session = await stripe().checkout.sessions.retrieve(sessionId);
160	    const userId = session.metadata?.nxeonUserId;
161	    const raw = session.metadata?.nxeonResize;
162	    if (!userId || !raw || session.payment_status !== "paid") return null;
163	    const parsed = JSON.parse(raw) as { serverId: string; planId: string; chargeCents: number };
164	    return { userId, serverId: parsed.serverId, planId: parsed.planId, chargeCents: parsed.chargeCents };
165	  } catch {
166	    return null;
167	  }
168	}
169	
170	/** For the confirm route: the order intent attached to a paid session, if any. */
171	export async function getCheckoutOrderIntent(
172	  sessionId: string,
173	): Promise<{ userId: string; intent: OrderIntent } | null> {
174	  if (!stripeConfigured()) return null;
175	  try {
176	    const session = await stripe().checkout.sessions.retrieve(sessionId);
177	    const userId = session.metadata?.nxeonUserId;
178	    const raw = session.metadata?.nxeonOrder;
179	    if (!userId || !raw || session.payment_status !== "paid") return null;
180	    return { userId, intent: JSON.parse(raw) as OrderIntent };
181	  } catch {
182	    return null;
183	  }
184	}
185	
186	/**
187	 * Credit a user's wallet for a completed Checkout session, idempotently.
188	 * Called from both the success-redirect confirm route (works without HTTPS)
189	 * and the webhook (belt-and-suspenders once HTTPS is available).
190	 * Returns true if a credit was applied this call.
191	 */
192	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
193	  const session = await stripe().checkout.sessions.retrieve(sessionId);
194	  const userId = session.metadata?.nxeonUserId;
195	  const cents = session.amount_total ?? 0;
196	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
197	
198	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
199	  // session id inside the description.
200	  const legacy = await db.walletTransaction.findFirst({
201	    where: { stripeSessionId: null, description: { contains: session.id } },
202	  });
203	  if (legacy) return false;
204	
205	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
206	  // read-then-write check. The confirm-redirect and the webhook can arrive
207	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
208	  // only the database can safely decide the winner. P2002 == already credited.
209	  try {
210	    await db.$transaction([
211	      db.walletTransaction.create({
212	        data: {
213	          userId,
214	          amountCents: cents,
215	          description: `Stripe payment (${session.id})`,
216	          stripeSessionId: session.id,
217	        },
218	      }),
219	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
220	      db.notification.create({
221	        data: {
222	          userId,
223	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
224	          href: "/dashboard/billing",
225	        },
226	      }),
227	      // PAID invoice for the top-up. Created in the SAME guarded transaction as
228	      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
229	      // the credit idempotent also prevents a duplicate invoice on replay.
230	      db.invoice.create({
231	        data: invoiceCreateData({
232	          userId,
233	          description: "Wallet top-up",
234	          status: "PAID",
235	          lineItems: [
236	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
237	          ],
238	        }),
239	      }),
240	    ]);
241	  } catch (e) {
242	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
243	    throw e;
244	  }
245	  // A funded wallet is the referred user's first paid action — reward both sides.
246	  try {
247	    const { maybeRewardReferral } = await import("./actions-growth");
248	    await maybeRewardReferral(userId);
249	  } catch { /* best-effort */ }
250	  try {
251	    const u = await db.user.findUnique({ where: { id: userId } });
252	    if (u) {
253	      const { sendMail, emails } = await import("./mailer");
254	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
255	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
256	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
257	      // account email off. This is the one send site where that toggle actually
258	      // bites today, so it is the one that made the switch a lie.
259	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt" });
260	    }
261	  } catch { /* best-effort */ }
262	  return true;
263	}
