1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	import { prorateUpgradeCents, remainingMonths } from "./proration";
8	
9	/** Average calendar month in ms (365.25/12 ≈ 30.44d) for duration-based proration. */
10	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
11	
12	export class ResizeError extends Error {}
13	
14	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
15	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
16	
17	function loadServer(serverId: string) {
18	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
19	}
20	function loadPlan(planId: string) {
21	  return db.plan.findUnique({ where: { id: planId } });
22	}
23	
24	export type ResizeQuote = {
25	  server: NonNullable<QuotedServer>;
26	  newPlan: QuotedPlan;
27	  prorateCents: number;
28	};
29	
30	/**
31	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
32	 * duration (monthly price difference for every remaining month; null expiresAt
33	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
34	 * any guard failure. Does NOT check ownership — callers must do that.
35	 *
36	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
37	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
38	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
39	 * completely alone. Two things follow, and both are deliberate:
40	 *
41	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
42	 *     prices. The extra-disk surcharge is identical before and after the resize
43	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
44	 *     must never be added here. It keeps being billed, unchanged, by the renewal
45	 *     sweep, which reads `extraDiskGB` directly.
46	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
47	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
48	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
49	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
50	 *     and the whole resize would hard-fail.)
51	 *
52	 * The disk-grow guard below intentionally compares PLAN disks, not effective
53	 * disks: since the extra is added to both sides, a target plan with an equal or
54	 * larger disk can never shrink the effective disk.
55	 */
56	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
57	  const server = await loadServer(serverId);
58	  if (!server) throw new ResizeError("Not found");
59	  const newPlan = await loadPlan(planId);
60	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
61	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
62	  if (newPlan.diskGB < server.plan.diskGB) {
63	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
64	  }
65	  if (newPlan.priceCents < server.plan.priceCents) {
66	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
67	  }
68	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
69	
70	  let prorateCents = 0;
71	  if (!server.isFree && server.expiresAt) {
72	    // Price the upgrade at the term discount AND the rate THIS SERVER'S TERM WAS
73	    // SOLD AT (`server.termPromoPercent`, persisted at every point a term is
74	    // bought). Using the raw list-price delta (as this did until 2026-07-25)
75	    // overcharged by the whole discount stack: on a 36-month term with a 30% promo
76	    // running, $1,044.45 to upgrade versus $665.08 to simply buy the same plan
77	    // outright for the same end date. Pricing off `currentPromo(now)` instead (as
78	    // it did until 2026-07-26) was worse: the customer picked the rate by picking
79	    // the date, upgrading under Cyber Monday's 45% and downgrading under the 15%
80	    // Launch Sale to pocket the spread. Shared with the downgrade credit and with
81	    // the client picker via lib/proration.ts so displayed, charged and credited
82	    // cannot drift apart.
83	    //
84	    // `remainingMonths` covers EVERY month left on `expiresAt` and takes no cap —
85	    // see the note on it. Charging the full stacked duration here is what makes the
86	    // mirror-image downgrade credit safe to pay out over the same duration: after
87	    // this charge the customer has genuinely paid the new plan's rate for every one
88	    // of those months. Capping this side alone would mint money on a round trip;
89	    // capping the credit side alone destroyed $362.88 of it until 2026-07-26.
90	    prorateCents = prorateUpgradeCents({
91	      fromMonthlyCents: server.plan.priceCents,
92	      toMonthlyCents: newPlan.priceCents,
93	      termMonths: server.termMonths,
94	      termPromoPercent: server.termPromoPercent,
95	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
96	    });
97	  }
98	  return { server, newPlan, prorateCents };
99	}
100	
101	/**
102	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
103	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
104	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
105	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
106	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
107	 *
108	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
109	 * amount the customer paid into their wallet at checkout so the debit here nets to
110	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
111	 * spend the just-credited funds). The wallet path omits it and debits the quote.
112	 */
113	export async function applyResize(opts: {
114	  serverId: string;
115	  planId: string;
116	  actorUserId: string;
117	  chargeCents?: number;
118	}): Promise<void> {
119	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
120	  const prorateCents = opts.chargeCents ?? quoted;
121	
122	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
123	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
124	
125	  try {
126	    await db.$transaction(async (tx) => {
127	      if (prorateCents > 0) {
128	        await debitWallet(tx, server.userId, prorateCents);
129	        await tx.walletTransaction.create({
130	          data: {
131	            userId: server.userId,
132	            amountCents: -prorateCents,
133	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
134	          },
135	        });
136	        // PAID invoice for the proration charge (one per user-initiated resize).
137	        await tx.invoice.create({
138	          data: invoiceCreateData({
139	            userId: server.userId,
140	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
141	            status: "PAID",
142	            lineItems: [
143	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
144	            ],
145	          }),
146	        });
147	      }
148	      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
149	      // not re-base the term — `expiresAt` is untouched and no new months are sold —
150	      // it only moves the customer to a different plan at the rate they already
151	      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
152	      // to zero: both halves read the same stored basis. (This is also why the basis
153	      // is stored as a percent rather than a $/mo figure: a cents rate would have to
154	      // be rewritten here, and that rewrite is one more place to get it wrong.)
155	      //
156	      // Record the amount charged on the job so the worker's RESIZE handler can
157	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
158	      // resize terminally fails — money is committed here, before the job runs.
159	      await tx.job.create({
160	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
161	      });
162	      await tx.auditLog.create({
163	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
164	      });
165	    });
166	  } catch (e) {
167	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
168	    throw e;
169	  }
170	}
