1	import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
2	
3	/**
4	 * What "Renew now" costs, and how long it buys — ONE definition, used by the
5	 * button that quotes it and by the action that charges it.
6	 *
7	 * WHY THIS FILE EXISTS. Real incident, 2026-07-26 QA (observed, not theorised):
8	 * the button read
9	 *
10	 *     Renew now (+30 days, $8.99)
11	 *
12	 * and charged **$97.09**, advancing the expiry by **twelve months**. The label
13	 * hardcoded the string "+30 days" and the plan's MONTHLY price, while `renewNow`
14	 * has always charged `vpsTermPriceCents` for `termMonths`. A 10.8× overcharge on
15	 * Starter/12-month, 28.8× on Max/36-month, with no confirmation step between the
16	 * click and the debit.
17	 *
18	 * This is the same defect that produced the $8.99-shown/$6.29-charged bug and the
19	 * $379 resize overcharge: a price computed twice, in two places, by two people.
20	 * `lib/proration.ts` exists because of that pattern and this file follows it —
21	 * the quote and the charge cannot drift because they are the same function.
22	 *
23	 * Renewals deliberately bill the REGULAR term price with no promotional discount
24	 * (promos are first-term introductory offers), so no promo basis is taken here.
25	 * See `Server.termPromoPercent` and `lib/promotions.ts`.
26	 */
27	export type RenewalQuoteInput = {
28	  /** The plan's monthly list price, in cents. */
29	  planPriceCents: number;
30	  /** The server's committed term. Renewal always buys exactly this many months. */
31	  termMonths: number;
32	  /** Whether a dedicated IP is ACTUALLY allocated — not merely requested. */
33	  hasDedicatedIp: boolean;
34	  /** Current per-month price of a dedicated IP, in cents. */
35	  dedicatedIpMonthlyCents: number;
36	  /** Current per-month surcharge for permanently-added root disk, in cents. */
37	  extraDiskMonthlyCents: number;
38	};
39	
40	export type RenewalQuote = {
41	  /** Total charged, in cents. */
42	  totalCents: number;
43	  /** Months the expiry advances by. */
44	  months: number;
45	  /** Human label for the duration, e.g. "12 months" / "1 month". */
46	  durationLabel: string;
47	};
48	
49	export function renewalQuote(input: RenewalQuoteInput): RenewalQuote {
50	  const term = vpsTerm(input.termMonths);
51	  const months = term.months;
52	  const totalCents =
53	    vpsTermPriceCents(input.planPriceCents, months) +
54	    (input.hasDedicatedIp ? input.dedicatedIpMonthlyCents * months : 0) +
55	    input.extraDiskMonthlyCents * months;
56	  return {
57	    totalCents,
58	    months,
59	    durationLabel: months === 1 ? "1 month" : `${months} months`,
60	  };
61	}
