/* ------------------------------------------------------------------ *
 * H2. Stripe order confirm re-priced AFTER the card was charged and took
 *     the difference out of the wallet.
 *
 * The Checkout session carried the customer's INTENT but never the quoted
 * total, so the confirm route re-ran `orderQuote` — including a fresh
 * `currentPromo(new Date())` — and debited whatever came back. The card had
 * already cleared for the old total's share. The gap came out of the wallet
 * with no new consent; with no balance, the payment was captured and no
 * server was created.
 *
 * The price is now fixed ONCE, before the card is charged, and carried on the
 * session as `nxeonOrderPrice`. Same shape lib/resize.ts and lib/disk-expand.ts
 * have always used — the order path was the one that re-derived it.
 * ------------------------------------------------------------------ */

/** A promo-rotation window that really exists in lib/promotions.ts. */
const DURING_SUMMER = new Date("2026-08-01T12:00:00.000Z"); // Summer Sale, 30%
const AFTER_SUMMER = new Date("2026-08-12T12:00:00.000Z"); // gap -> Launch Sale, 15%

test("the rotation that re-priced a paid order is real, and it moves real money", () => {
  const before = currentPromo(DURING_SUMMER);
  const after = currentPromo(AFTER_SUMMER);
  assert.equal(before.discountPercent, 30, "Summer Sale");
  assert.equal(after.discountPercent, 15, "the always-on Launch Sale fallback");
  // Starter $8.99 on the Annual term — the order from the rehearsal.
  const regular = vpsTermPriceCents(899, 12);
  const soldAt = promoPriceCents(regular, before);
  const repricedAt = promoPriceCents(regular, after);
  assert.equal(soldAt, 6796);
  assert.equal(repricedAt, 8253);
  // The customer's card was charged against 6796. Re-quoting at confirm debited
  // 8253 from the wallet, so $14.57 of their balance vanished with no consent —
  // and with an empty wallet the whole order failed after the money was taken.
  assert.equal(repricedAt - soldAt, 1457, "the silent wallet draw, to the cent");
});

test("a sold price round-trips through Stripe metadata unchanged", () => {
  const sold = orderPriceOf({
    chargeCents: promoPriceCents(vpsTermPriceCents(899, 12), currentPromo(DURING_SUMMER)),
    promo: currentPromo(DURING_SUMMER),
  });
  assert.deepEqual(sold, { chargeCents: 6796, promoPercent: 30, promoName: "Summer Sale" });
  // Stripe metadata values are strings, and this one is written and read back on
  // opposite sides of a browser redirect.
  const roundTripped = parseOrderPrice(JSON.stringify(sold));
  assert.deepEqual(roundTripped, sold);
  // It also has to fit: Stripe caps a metadata value at 500 characters and the
  // writer slices to 490. A price that can be truncated is a price that can be lost.
  assert.ok(JSON.stringify(sold).length < 200, "the stamped price is nowhere near the metadata cap");
});

test("the settled total does not move when the promo rotates under it", () => {
  const sold = orderPriceOf({
    chargeCents: promoPriceCents(vpsTermPriceCents(899, 12), currentPromo(DURING_SUMMER)),
    promo: currentPromo(DURING_SUMMER),
  });
  // What placeOrder now bills: `sold.chargeCents ?? quote.chargeCents`. The stamped
  // value is a constant — no date, no promo lookup, nothing that a browser redirect
  // taking an hour can change.
  const settled = parseOrderPrice(JSON.stringify(sold))!.chargeCents;
  assert.equal(settled, 6796);
  assert.notEqual(settled, promoPriceCents(vpsTermPriceCents(899, 12), currentPromo(AFTER_SUMMER)));
  // And the rate travels with it, because Server.termPromoPercent records the rate
  // the term was SOLD at. Stamping today's 15% against a 30% price would hand every
  // later proration the wrong basis (see lib/proration.ts).
  assert.equal(parseOrderPrice(JSON.stringify(sold))!.promoPercent, 30);
});

test("a malformed stamped price is refused outright rather than half-believed", () => {
  // The fallback is a fresh quote — the old behaviour. That is only safe if a
  // partially-valid price can never be accepted: a total without its rate would be
  // charged at one price and prorated against another.
  for (const bad of [
    undefined,
    null,
    "",
    "not json",
    "{}",
    '{"chargeCents":"6796","promoPercent":30}',
    '{"chargeCents":6796.5,"promoPercent":30}',
    '{"chargeCents":-1,"promoPercent":30}',
    '{"chargeCents":6796}',
    '{"chargeCents":6796,"promoPercent":101}',
    '{"chargeCents":6796,"promoPercent":-1}',
  ]) {
    assert.equal(parseOrderPrice(bad), null, `must reject ${JSON.stringify(bad)}`);
  }
  // A price with no promo name is still a valid price — the name is ledger text.
  assert.deepEqual(parseOrderPrice('{"chargeCents":6796,"promoPercent":0}'), {
    chargeCents: 6796,
    promoPercent: 0,
    promoName: "",
  });
});

test("the order path stamps the price before the card is charged and settles it after", () => {
  const stripe = code("../lib/stripe.ts");
  const order = code("../lib/order.ts");
  const fulfil = code("../lib/fulfil-checkout.ts");
  assert.match(stripe, /nxeonOrderPrice: JSON\.stringify\(price\)/, "the total is stamped on the session");
  assert.match(
    stripe,
    /sold \?\? orderPriceOf\(await orderQuote\(intent\)\)/,
    "the price is fixed at session creation — before any money moves",
  );
  assert.match(
    stripe,
    /if \(price\.chargeCents < amountCents\)/,
    "a card leg larger than the order total is refused, not discovered at confirm",
  );
  assert.match(stripe, /sold: parseOrderPrice\(session\.metadata\?\.nxeonOrderPrice\)/, "and read back on confirm");
  assert.match(fulfil, /placeOrder\(user, order\.intent, order\.sold\)/, "confirm settles the stamped price");
  assert.match(
    order,
    /const chargeCents = sold\?\.chargeCents \?\? quote\.chargeCents/,
    "placeOrder bills the sold price when there is one",
  );
  assert.match(
    order,
    /termPromoPercent: freeRequested \? 100 : promoPercent/,
    "and records the rate it was SOLD at, not the promo running now",
  );
});

/* ------------------------------------------------------------------ *
 * H3. A card-paid purchase produced TWO PAID invoices and doubled
 *     "Paid · lifetime".
 *
 * The wallet is the settlement bus for a card-paid purchase: the card amount
 * is credited in, the purchase debits the full total back out.
 * `creditCheckoutSession` documented that credit as a PAID "Wallet top-up"
 * for EVERY paid session, and then the purchase issued its own invoice. One
 * $82.53 order became $165.06 of lifetime spend on the customer's own
 * billing history.
 * ------------------------------------------------------------------ */

test("a session that funds a purchase is not a wallet top-up", () => {
  const order = { nxeonUserId: "u1", nxeonOrder: '{"planId":"p"}', nxeonOrderPrice: '{"chargeCents":8253,"promoPercent":15,"promoName":"Launch Sale"}' };
  const resize = { nxeonUserId: "u1", nxeonResize: '{"serverId":"s","planId":"p","chargeCents":1234}' };
  const expand = { nxeonUserId: "u1", nxeonDiskExpand: '{"serverId":"s","addGB":50,"chargeCents":1234}' };
  const topUp = { nxeonUserId: "u1" };
  assert.equal(isPurchaseLegSession(order), true, "a VPS order");
  assert.equal(isPurchaseLegSession(resize), true, "an upgrade — same double-invoice, never reported");
  assert.equal(isPurchaseLegSession(expand), true, "a disk expansion — likewise");
  assert.equal(isPurchaseLegSession(topUp), false, "a real top-up IS a product and keeps its invoice");
  assert.equal(isPurchaseLegSession(null), false);
  assert.equal(isPurchaseLegSession(undefined), false);
});

test("one card charge produces exactly one PAID invoice", () => {
  // The invoices page sums every PAID invoice into "Paid · lifetime"
  // (app/dashboard/invoices/page.tsx). The rehearsal's $82.53 annual purchase
  // produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53` = $165.06.
  const purchaseCents = 8253;
  const documents = [
    { description: "Starter VPS — Annual", amountCents: purchaseCents, status: "PAID" as const },
    // The top-up document is no longer written for a purchase leg.
    ...(isPurchaseLegSession({ nxeonOrder: "{}" })
      ? []
      : [{ description: "Wallet top-up", amountCents: purchaseCents, status: "PAID" as const }]),
  ];
  assert.equal(documents.length, 1, "two documents for one payment is the defect");
  assert.equal(
    documents.reduce((s, d) => s + d.amountCents, 0),
    purchaseCents,
    "lifetime paid must equal the card statement, not twice it",
  );
});

test("the top-up invoice is written only when the session really is a top-up", () => {
  const stripe = code("../lib/stripe.ts");
  assert.match(
    stripe,
    /const purchaseLeg = isPurchaseLegSession\(session\.metadata\)/,
    "the credit path asks what the session was for",
  );
  assert.match(stripe, /if \(!purchaseLeg\) \{/, "and only documents a genuine top-up");
  // The credit itself, the ledger row and the notification are unconditional: the
  // money really did move and must stay reconcilable either way.
  const creditFn = stripe.slice(stripe.indexOf("export async function creditCheckoutSession"));
  assert.match(creditFn, /stripeSessionId: session\.id/, "the credit keeps its UNIQUE-index idempotency");
  assert.ok(
    creditFn.indexOf("walletTransaction.create") < creditFn.indexOf("if (!purchaseLeg)"),
    "the ledger row is written for every paid session, purchase leg or not",
  );
  // A receipt that calls a server purchase a "wallet top-up" is the same false
  // statement in the inbox instead of the invoice list.
  assert.match(creditFn, /purchaseLeg \? "your Nxeon order" : "wallet top-up"/);
});

