/**
 * End-to-end exercise of the card-paid deploy path against SANDBOX Stripe.
 *
 *   node --env-file .env  (run via tsx from the scratch app dir)
 *   npx tsx drive.ts <label>
 *
 * Scenario: customer with a partial wallet balance buys Starter / Annual.
 * The card leg goes to Stripe (test card 4242). BETWEEN creating the checkout
 * session and paying it, the plan's list price is doubled in the database — a
 * faithful stand-in for the promo rotating under a paid order, which is what
 * H2 describes. A correct confirm settles the price the customer was shown.
 */
import { chromium } from "playwright";
import { PrismaClient } from "@prisma/client";

const BASE = "http://127.0.0.1:3100";
const label = process.argv[2] ?? "run";
const email = `h2h3.${label}.${Date.now()}@example.com`;
const password = "Testpass123";
const hostname = `probe-${label}`;
const db = new PrismaClient();

const money = (c: number) => `$${(c / 100).toFixed(2)}`;

async function main() {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 1100 } });
  const page = await ctx.newPage();
  const notes: string[] = [];

  // --- register -----------------------------------------------------------
  await page.goto(`${BASE}/register`);
  await page.fill('input[name="name"]', "QA Probe");
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', password);
  await page.click('button[type="submit"]');
  await page.waitForURL(/dashboard/, { timeout: 30000 });

  const user = await db.user.findUniqueOrThrow({ where: { email } });
  // Ordering is gated on a verified address (another agent's B4 work); this is a
  // scratch DB, so mark it verified rather than round-tripping a mail.
  // Give them a PARTIAL balance so the order is a wallet+card split — the case
  // where a re-price has somewhere silent to take the difference from.
  await db.user.update({
    where: { id: user.id },
    data: { emailVerifiedAt: new Date(), balanceCents: 2000 },
  });

  const plan = await db.plan.findUniqueOrThrow({ where: { slug: "starter" } });
  notes.push(`plan Starter @ ${money(plan.priceCents)}/mo, wallet starts at ${money(2000)}`);

  // --- wizard -------------------------------------------------------------
  await page.goto(`${BASE}/dashboard/deploy`);
  await page.getByRole("button", { name: /^Starter/ }).click();
  await page.getByRole("button", { name: "Continue →" }).click(); // -> Install
  await page.getByRole("button", { name: /Ubuntu/ }).first().click();
  await page.getByRole("button", { name: "Continue →" }).click(); // -> Add-ons
  await page.getByRole("button", { name: "Continue →" }).click(); // -> Access
  await page.fill('input[placeholder="my-server"]', hostname);
  await page.getByRole("button", { name: "Continue →" }).click(); // -> Review
  await page.getByRole("button", { name: /^Annual/ }).click();
  await page.waitForTimeout(300);

  // What the Review step SAYS, verbatim — H1 lives here.
  const termCards = await page.locator("button.card.relative").allInnerTexts();
  const reviewText = await page.locator("form").innerText();
  const disclosure =
    reviewText.split("\n").find((l) => l.includes("off your first term applied")) ?? "(none)";
  const dueLine = reviewText.split("\n").find((l, i, a) => a[i - 1] === "Due today") ?? "(none)";
  const cardLine = reviewText.split("\n").find((l, i, a) => a[i - 1] === "Pay by card") ?? "(none)";

  // --- deploy -> Stripe ---------------------------------------------------
  await page.getByRole("button", { name: /^Deploy/ }).click();
  await page.waitForURL(/checkout\.stripe\.com/, { timeout: 60000 });
  const stripeUrl = page.url();

  const session = await (async () => {
    const Stripe = (await import("stripe")).default;
    const s = new Stripe(process.env.STRIPE_SECRET_KEY!);
    const list = await s.checkout.sessions.list({ limit: 5 });
    return list.data.find((x) => x.metadata?.nxeonUserId === user.id)!;
  })();
  notes.push(`stripe session ${session.id}: card leg ${money(session.amount_total ?? 0)}`);
  notes.push(`  metadata.nxeonOrderPrice = ${session.metadata?.nxeonOrderPrice ?? "(absent)"}`);

  // THE RE-PRICE. Double the plan's list price while the customer is on Stripe's
  // page. Any confirm that re-quotes will now compute a different, larger total.
  await db.plan.update({ where: { id: plan.id }, data: { priceCents: plan.priceCents * 2 } });
  notes.push(`  >>> plan re-priced to ${money(plan.priceCents * 2)}/mo while the card was being entered`);

  // --- pay with the sandbox test card -------------------------------------
  await page.fill('input[name="cardNumber"]', "4242424242424242");
  await page.fill('input[name="cardExpiry"]', "12 / 34");
  await page.fill('input[name="cardCvc"]', "123");
  await page.fill('input[name="billingName"]', "QA Probe");
  const zip = page.locator('input[name="billingPostalCode"]');
  if (await zip.count()) await zip.fill("94107");
  await page.getByTestId("hosted-payment-submit-button").click();
  await page.waitForURL((u) => u.host === "127.0.0.1:3100", { timeout: 120000 });
  const landed = page.url();
  await page.waitForTimeout(2500);

  // --- what actually happened --------------------------------------------
  const after = await db.user.findUniqueOrThrow({ where: { id: user.id } });
  const ledger = await db.walletTransaction.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "asc" },
  });
  const invoices = await db.invoice.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "asc" },
  });
  const servers = await db.server.findMany({ where: { userId: user.id } });

  console.log(`\n================ ${label.toUpperCase()} ================`);
  for (const n of notes) console.log(n);
  console.log("\n-- Review step, verbatim --");
  for (const c of termCards) console.log("  [term card] " + c.replace(/\n/g, " | "));
  console.log("  Due today   :", dueLine);
  console.log("  Pay by card :", cardLine);
  console.log("  disclosure  :", disclosure);
  console.log("\n-- after payment --");
  console.log("  landed on   :", landed.replace(BASE, ""));
  console.log("  stripe page :", stripeUrl.slice(0, 60) + "…");
  console.log("  wallet now  :", money(after.balanceCents));
  console.log("  ledger:");
  for (const t of ledger) console.log(`    ${t.amountCents >= 0 ? "+" : ""}${t.amountCents}  ${t.description}`);
  console.log("  invoices:");
  for (const i of invoices) console.log(`    ${i.status.padEnd(5)} ${String(i.amountCents).padStart(6)}  ${i.description}`);
  const paidLifetime = invoices.filter((i) => i.status === "PAID").reduce((s, i) => s + i.amountCents, 0);
  console.log(`  PAID lifetime (what /dashboard/invoices reports): ${money(paidLifetime)}`);
  console.log("  servers:", servers.map((s) => `${s.hostname} term=${s.termMonths}mo promoPct=${s.termPromoPercent}`).join(", ") || "(none)");
  const cardCharged = session.amount_total ?? 0;
  const debited = ledger.filter((t) => t.amountCents < 0).reduce((s, t) => s + t.amountCents, 0);
  console.log(`\n  card charged ${money(cardCharged)} | wallet debited ${money(-debited)} | balance ${money(2000)} -> ${money(after.balanceCents)}`);

  await browser.close();
  await db.$disconnect();
}

