const email = `topup.${Date.now()}@example.com`;
const db = new PrismaClient();
const money = (c: number) => `$${(c / 100).toFixed(2)}`;

async function main() {
  const browser = await chromium.launch();
  const page = await (await browser.newContext()).newPage();
  await page.goto(`${BASE}/register`);
  const accept = page.getByRole("button", { name: /Accept all/i });
  if (await accept.count()) await accept.first().click();
  await page.fill('input[name="name"]', "Top Up");
  await page.fill('input[name="email"]', email);
  await page.fill('input[name="password"]', "Testpass123");
  await page.locator("form button.btn-primary").first().click();
  await page.waitForURL(/dashboard/, { timeout: 30000 });

  // A PLAIN wallet top-up: no order, no resize, no disk expansion. This session
  // carries none of the purchase metadata keys, so it must keep its invoice.
  const url = await page.evaluate(async () => {
    const r = await fetch("/api/stripe/checkout", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ amount: 25 }),
    });
    return (await r.json()).url as string;
  });
  await page.goto(url);
  await page.fill('input[name="cardNumber"]', "4242424242424242");
  await page.fill('input[name="cardExpiry"]', "12 / 34");
  await page.fill('input[name="cardCvc"]', "123");
  await page.fill('input[name="billingName"]', "Top Up");
  const zip = page.locator('input[name="billingPostalCode"]');
  if (await zip.count()) await zip.fill("94107");
  await page.getByTestId("hosted-payment-submit-button").click();
  await page.waitForURL((u) => u.host === "127.0.0.1:3100", { timeout: 120000 });
  await page.waitForTimeout(2500);

  const u = await db.user.findUniqueOrThrow({ where: { email } });
  const inv = await db.invoice.findMany({ where: { userId: u.id } });
  const led = await db.walletTransaction.findMany({ where: { userId: u.id } });
  console.log("\n================ PLAIN TOP-UP (regression check) ================");
  console.log("  landed on :", page.url().replace(BASE, ""));
  console.log("  balance   :", money(u.balanceCents));
  console.log("  ledger    :", led.map((t) => `${t.amountCents} ${t.description.slice(0, 30)}`).join(" | "));
  console.log("  invoices  :", inv.map((i) => `${i.status} ${i.amountCents} ${i.description}`).join(" | ") || "(NONE — regression!)");
  await browser.close();
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });
